package com.ftk.tpip.catalog.domain.model;
import com.ftk.tpip.shared.AssetCode;import java.time.Instant;import java.util.Objects;
public record CanonicalContract(Long id,long operationId,AssetCode contractCode,String contractName,ContractKind contractKind,String description,CanonicalContractStatus status,long rowVersion,Instant createdAt,Instant updatedAt){
public CanonicalContract{if(id!=null&&id<=0)throw new IllegalArgumentException("id must be positive");if(operationId<=0)throw new IllegalArgumentException("operationId must be positive");contractCode=Objects.requireNonNull(contractCode);contractName=req(contractName,"contractName",200);contractKind=Objects.requireNonNull(contractKind);description=opt(description,1000);status=Objects.requireNonNull(status);if(rowVersion<0)throw new IllegalArgumentException("rowVersion must not be negative");}
public static CanonicalContract create(long operationId,AssetCode code,String name,ContractKind kind,String description){return new CanonicalContract(null,operationId,code,name,kind,description,CanonicalContractStatus.ACTIVE,0,null,null);}public CanonicalContract revise(String name,String description,CanonicalContractStatus status,long version){if(id==null)throw new IllegalStateException("unsaved contract cannot be revised");return new CanonicalContract(id,operationId,contractCode,name,contractKind,description,status,version,createdAt,updatedAt);}private static String req(String v,String f,int m){String n=Objects.requireNonNull(v,f+" must not be null").trim();if(n.isEmpty()||n.length()>m)throw new IllegalArgumentException(f+" is blank or too long");return n;}private static String opt(String v,int m){if(v==null||v.isBlank())return null;String n=v.trim();if(n.length()>m)throw new IllegalArgumentException("description is too long");return n;}}
